const text = String($json.content ?? '').trim();

if (!text) {
  throw new Error('Không tìm thấy $json.content để chia chunk.');
}

// Có thể chỉnh theo model embedding.
// Với FAQ kỹ thuật, 4000–5000 ký tự/chunk là mức thực tế khá ổn.
const MAX_CHARS = 4500;

// Đúng với separator ở node gộp dữ liệu của bạn.
const FAQ_SEPARATOR = '\n\n---\n\n';

// Tách chuỗi lớn trở lại thành từng FAQ hoàn chỉnh.
// Như vậy chunker sẽ ưu tiên KHÔNG cắt giữa một FAQ.
let faqBlocks = text
  .split(FAQ_SEPARATOR)
  .map(v => v.trim())
  .filter(Boolean);

if (!faqBlocks.length) {
  faqBlocks = [text];
}

const chunks = [];

let currentBlocks = [];
let currentLength = 0;

function flushChunk() {
  if (!currentBlocks.length) return;

  chunks.push({
    content: currentBlocks.join(FAQ_SEPARATOR),
    faq_count: currentBlocks.length
  });

  currentBlocks = [];
  currentLength = 0;
}

// Nếu một FAQ đơn lẻ dài hơn MAX_CHARS thì buộc phải chia.
// Khi chia, lặp lại phần context chính để mỗi phần vẫn có nghĩa.
function splitOversizedFaq(block) {
  if (block.length <= MAX_CHARS) {
    return [block];
  }

  const lines = block.split('\n');

  const faqTitle =
    lines.find(l => /^FAQ\s+\d+/i.test(l.trim()))?.trim() || 'FAQ';

  const versionLine =
    lines.find(l => /^Phiên bản sử dụng:/i.test(l.trim()))?.trim() || '';

  const supportLine =
    lines.find(l => /^Nội dung cần hỗ trợ:/i.test(l.trim()))?.trim() || '';

  const errorLine =
    lines.find(l => /^Loại lỗi:/i.test(l.trim()))?.trim() || '';

  const severityLine =
    lines.find(l => /^Mức độ:/i.test(l.trim()))?.trim() || '';

  const solutionMatch = block.match(
    /Hướng giải quyết:\s*([\s\S]*?)(?:\nMức độ:|$)/i
  );

  const solution = solutionMatch
    ? solutionMatch[1].trim()
    : block;

  const contextLines = [
    faqTitle,
    versionLine,
    supportLine,
    errorLine
  ].filter(Boolean);

  const context = contextLines.join('\n');

  // Trừ phần context để tổng chunk không vượt quá MAX_CHARS.
  const MAX_BODY = Math.max(
    800,
    MAX_CHARS - context.length - severityLine.length - 120
  );

  const parts = [];
  let start = 0;
  let partNo = 1;

  while (start < solution.length) {
    let end = Math.min(start + MAX_BODY, solution.length);

    // Cố gắng cắt tại điểm tự nhiên thay vì cắt giữa từ.
    if (end < solution.length) {
      const slice = solution.slice(start, end);

      const candidates = [
        slice.lastIndexOf('\n\n'),
        slice.lastIndexOf('. '),
        slice.lastIndexOf('; '),
        slice.lastIndexOf(', ')
      ];

      const best = Math.max(...candidates);

      if (best > MAX_BODY * 0.6) {
        end = start + best + 1;
      }
    }

    const body = solution.slice(start, end).trim();

    const rebuilt = [
      `${faqTitle} - Phần ${partNo}`,
      versionLine,
      supportLine,
      errorLine,
      'Hướng giải quyết:',
      body,
      severityLine
    ]
      .filter(Boolean)
      .join('\n');

    parts.push(rebuilt);

    start = end;
    partNo++;
  }

  return parts;
}

// Gom nhiều FAQ hoàn chỉnh vào cùng một chunk.
// Chỉ sang chunk mới khi thêm FAQ tiếp theo sẽ vượt MAX_CHARS.
for (const faq of faqBlocks) {
  const logicalParts = splitOversizedFaq(faq);

  for (const part of logicalParts) {
    const separatorLength =
      currentBlocks.length ? FAQ_SEPARATOR.length : 0;

    const projectedLength =
      currentLength + separatorLength + part.length;

    if (
      currentBlocks.length > 0 &&
      projectedLength > MAX_CHARS
    ) {
      flushChunk();
    }

    currentBlocks.push(part);

    currentLength +=
      (currentBlocks.length > 1 ? FAQ_SEPARATOR.length : 0) +
      part.length;
  }
}

flushChunk();

